CREATE TABLE invoices (id uuid DEFAULT gen_random_uuid() NOT NULL,invoice_number text NOT NULL,invoice_date date DEFAULT CURRENT_DATE NOT NULL,financial_year_id uuid,customer_user_id uuid,customer_name text,customer_email text,customer_phone text,customer_gstin text,customer_state text,customer_state_code text,business_name text NOT NULL,business_gstin text NOT NULL,business_address text,business_state text,business_state_code text,subtotal numeric DEFAULT 0 NOT NULL,cgst_total numeric DEFAULT 0 NOT NULL,sgst_total numeric DEFAULT 0 NOT NULL,igst_total numeric DEFAULT 0 NOT NULL,total numeric DEFAULT 0 NOT NULL,status text DEFAULT 'issued'::text NOT NULL,invoice_type text DEFAULT 'invoice'::text NOT NULL,credit_note_for uuid,payment_method text,revenue_transaction_id uuid,city text,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL,notes text,due_date date,invoice_category text DEFAULT 'purchase'::text NOT NULL,payment_reference text,amount_paid numeric DEFAULT 0 NOT NULL,payment_status text DEFAULT 'paid'::text NOT NULL,credit_note_disposition text,discount_type text,discount_value numeric DEFAULT 0 NOT NULL,discount_amount numeric DEFAULT 0 NOT NULL);
CREATE TABLE invoice_line_items (id uuid DEFAULT gen_random_uuid() NOT NULL,invoice_id uuid NOT NULL,item_name text NOT NULL,item_type text DEFAULT 'service'::text NOT NULL,hsn_code text,sac_code text,quantity numeric DEFAULT 1 NOT NULL,unit_price numeric DEFAULT 0 NOT NULL,gst_rate numeric DEFAULT 0 NOT NULL,cgst_amount numeric DEFAULT 0 NOT NULL,sgst_amount numeric DEFAULT 0 NOT NULL,igst_amount numeric DEFAULT 0 NOT NULL,line_total numeric DEFAULT 0 NOT NULL,product_id uuid,sort_order integer DEFAULT 0 NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE revenue_transactions (id uuid DEFAULT gen_random_uuid() NOT NULL,transaction_type text NOT NULL,amount numeric DEFAULT 0 NOT NULL,currency text DEFAULT 'INR'::text NOT NULL,user_id uuid,guest_name text,guest_email text,guest_phone text,gateway_name text,gateway_order_ref text,gateway_payment_ref text,booking_id uuid,hours_transaction_id uuid,description text,status text DEFAULT 'confirmed'::text NOT NULL,original_transaction_id uuid,metadata jsonb DEFAULT '{}'::jsonb,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL,city text,product_id uuid,source_ref text,revenue_date date DEFAULT ((now() AT TIME ZONE 'Asia/Kolkata'::text))::date NOT NULL);
CREATE TABLE bookings (id uuid DEFAULT gen_random_uuid() NOT NULL,user_id uuid NOT NULL,city text NOT NULL,start_time timestamp with time zone NOT NULL,end_time timestamp with time zone NOT NULL,duration_minutes integer NOT NULL,status text DEFAULT 'confirmed'::text NOT NULL,calendar_event_id text,note text,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL,bay_id uuid,session_type text DEFAULT 'practice'::text NOT NULL,coach_name text,billing_status text DEFAULT 'immediate'::text NOT NULL,corporate_invoice_id uuid,invoice_id uuid,parent_booking_id uuid,corporate_account_id uuid);
CREATE TABLE gst_profiles (id uuid DEFAULT gen_random_uuid() NOT NULL,city text NOT NULL,legal_name text DEFAULT ''::text NOT NULL,gstin text DEFAULT ''::text NOT NULL,address text DEFAULT ''::text NOT NULL,state text DEFAULT ''::text NOT NULL,state_code text DEFAULT ''::text NOT NULL,invoice_prefix text DEFAULT 'INV'::text NOT NULL,invoice_start_number integer DEFAULT 1 NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL,default_service_gst_rate numeric DEFAULT 18 NOT NULL,default_sac_code text,is_gst_registered boolean DEFAULT true NOT NULL);
CREATE TABLE financial_years (id uuid DEFAULT gen_random_uuid() NOT NULL,label text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,is_active boolean DEFAULT false NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL,city text);
CREATE TABLE profiles (id uuid DEFAULT gen_random_uuid() NOT NULL,user_id uuid,display_name text,avatar_url text,handicap numeric,total_rounds integer DEFAULT 0,points integer DEFAULT 0,tier text DEFAULT 'bronze'::text,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL,email text,preferred_city text,apple_user_id text,user_type text DEFAULT 'registered'::text NOT NULL,phone text,extended_hours_access boolean DEFAULT false NOT NULL,billing_mode text DEFAULT 'standard'::text NOT NULL,corporate_account_id uuid,date_of_birth date,parent_email text,parent_consent_status text,parent_consent_token text,parent_consent_at timestamp with time zone);
CREATE TABLE recycled_invoice_numbers (id uuid DEFAULT gen_random_uuid() NOT NULL,gstin text NOT NULL,financial_year_id uuid NOT NULL,prefix text DEFAULT 'INV'::text NOT NULL,number integer NOT NULL,invoice_number_text text NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,doc_type text DEFAULT 'tax_invoice'::text NOT NULL);
CREATE TABLE bays (id uuid DEFAULT gen_random_uuid() NOT NULL,city text NOT NULL,name text NOT NULL,calendar_email text,open_time text DEFAULT '09:00'::text NOT NULL,close_time text DEFAULT '22:00'::text NOT NULL,is_active boolean DEFAULT true NOT NULL,sort_order integer DEFAULT 0 NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL,coaching_mode text DEFAULT 'instant'::text NOT NULL,coaching_hours numeric DEFAULT 1 NOT NULL,currency text DEFAULT 'INR'::text NOT NULL,coaching_cancellation_refund_hours numeric DEFAULT 0 NOT NULL,peak_start time without time zone DEFAULT '17:00:00'::time without time zone,peak_end time without time zone DEFAULT '21:00:00'::time without time zone,weekly_off_days integer[] DEFAULT '{}'::integer[] NOT NULL,extended_open_time time without time zone,extended_close_time time without time zone,extended_hours_enabled boolean DEFAULT false NOT NULL);
CREATE TABLE site_admin_cities (id uuid DEFAULT gen_random_uuid() NOT NULL,user_id uuid NOT NULL,city text NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE user_roles (id uuid DEFAULT gen_random_uuid() NOT NULL,user_id uuid NOT NULL,role text NOT NULL);
ALTER TABLE user_roles ADD UNIQUE(user_id,role);